package main

/*
#include <string.h>
#include <stdlib.h>
*/
import "C"
import (
	"fmt"
	"unsafe"
)

func cLen(s string) int {
	cs := C.CString(s)                 // C heap allocation
	defer C.free(unsafe.Pointer(cs))   // release it; cast through unsafe.Pointer
	n := C.strlen(cs)
	return int(n)
}

func main() {
	fmt.Println(cLen("hello")) // 5
}

