package solution

/*
#include <ctype.h>
#include <stdlib.h>
#include <string.h>

static char* upper(const char* s) {
    size_t n = strlen(s);
    char* out = malloc(n + 1);
    for (size_t i = 0; i < n; i++) out[i] = toupper((unsigned char)s[i]);
    out[n] = '\0';
    return out;
}
*/
import "C"
import "unsafe"

func Shout(s string) string {
	cs := C.CString(s)                 // Go string -> C char* (malloc)
	defer C.free(unsafe.Pointer(cs))   // free the input copy

	res := C.upper(cs)                 // C returns a NEW malloc'd buffer
	defer C.free(unsafe.Pointer(res))  // free the output copy too

	return C.GoString(res)             // copy C string into a Go string
}

