package solution

import "testing"

func TestShout(t *testing.T) {
	cases := []struct{ in, want string }{
		{"hello", "HELLO"},
		{"Go123", "GO123"},
		{"", ""},
	}
	for _, c := range cases {
		if got := Shout(c.in); got != c.want {
			t.Errorf("Shout(%q)=%q want %q", c.in, got, c.want)
		}
	}
}

